kl = Kinloom()

# --- stand-in for the game (plain Python: example values, small functions) ---

traffic = [
    {"id": "5th & Main",  "queue": 24, "wait_s": 71, "green_s": 30, "spillback": True},
    {"id": "Harbor Rd",   "queue": 6,  "wait_s": 18, "green_s": 30, "spillback": False},
    {"id": "Old Mill Ln", "queue": 14, "wait_s": 40, "green_s": 30, "spillback": False},
]

def jam_score(light):
    """0.0 (free flowing) .. 1.0 (gridlocked) for one intersection."""
    return min(1.0, light["queue"] / 40 + light["wait_s"] / 120 + (0.2 if light["spillback"] else 0.0))

def neighbours(light):
    return [o["id"] for o in traffic if o["id"] != light["id"]]

def apply_plan(light, plan):
    """Where the game would push the decision into the simulation."""
    light["green_s"] = plan["green_s"]
    light["offset_s"] = plan["offset_s"]
    light["mode"] = plan["mode"]

# --- the AI part: one character that retimes every light ---

kl.character("Traffic Control", "a calm city traffic engineer who keeps cars moving and never gridlocks a junction")

def retime(light):
    return kl.decide("Traffic Control", {
        "intersection": light["id"],
        "queue": light["queue"],
        "wait_seconds": light["wait_s"],
        "current_green_s": light["green_s"],
        "spillback": light["spillback"],
        "jam": round(jam_score(light), 2),
        "neighbours": neighbours(light),
    }, {
        "green_s": [8, 60],          # how long this light stays green
        "offset_s": [0, 30],         # when it turns green, to make a green wave
        "mode": ["rush", "normal", "clear"],
    })

# --- where the game would call it ---

for light in traffic:
    apply_plan(light, retime(light))

for light in traffic:
    print(light["id"], light["mode"], light["green_s"], "s green, offset", light["offset_s"])

