from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game (plain Python, no engine) ---
PLAYER = {"x": 0.0, "y": 0.0}

class Enemy:
    def __init__(self, i, x, y, hp=1.0, armed=True):
        self.id = "enemy-%d" % i
        self.x, self.y, self.hp, self.armed = x, y, hp, armed
        self.action, self.args = "idle", {}

    def dist_to_player(self):
        return ((self.x - PLAYER["x"]) ** 2 + (self.y - PLAYER["y"]) ** 2) ** 0.5

    def allies_near(self, enemies, radius=15.0):
        return sum(1 for e in enemies
                   if e is not self and ((e.x - self.x) ** 2 + (e.y - self.y) ** 2) ** 0.5 <= radius)

    def move(self, dx, dy, speed=1.0):
        self.x += dx * speed
        self.y += dy * speed

def apply_action(e, a):
    e.action, e.args = a["action"], a["args"]
    if e.action == "retreat":
        e.move(e.x - PLAYER["x"], e.y - PLAYER["y"], speed=2.0)
    elif e.action == "flank":
        e.move(-(PLAYER["y"] - e.y), PLAYER["x"] - e.x, speed=1.5)
    elif e.action == "charge":
        e.move(PLAYER["x"] - e.x, PLAYER["y"] - e.y, speed=a["args"].get("speed", 1.0))
    elif e.action == "shoot":
        pass  # fire a burst of a["args"]["burst"]

# --- the crowd's mind: declared once, decided locally for every unit, every frame ---
kl.mind("enemy", "an enemy soldier who avoids fair fights and swarms when it has numbers",
        senses={"hp": [0.0, 1.0], "dist": [0.0, 40.0], "allies": [0, 10],
                "armed": True, "target": ["idle", "alert", "fleeing"]},
        actions={"charge": {"speed": [1.0, 3.0]}, "shoot": {"burst": [1, 5]}, "flank": {}, "retreat": {}},
        rules={"retreat": ["hp low"],
               "shoot": ["armed", "dist below 20"],
               "flank": {"score": 0.8, "when": ["allies above 2", "target is alert"]},
               "charge": {"score": 0.5, "args": {"speed": "dist high"}}},
        learn=30)

# --- where the game loop would be: one frame ---
enemies = [Enemy(i, x=(i % 20) - 10.0, y=(i // 20) - 10.0, hp=1.0 - (i % 3) * 0.4) for i in range(200)]
player_state = "alert"

for e in enemies:
    senses = {"hp": e.hp, "dist": min(e.dist_to_player(), 40.0),
              "allies": min(e.allies_near(enemies), 10),
              "armed": e.armed, "target": player_state}
    a = kl.think("enemy", senses, who=e.id)
    apply_action(e, a)

# --- what those choices earned, and the round judged whole ---
for e in enemies:
    if e.hp < 0.5 and e.action == "retreat":
        kl.reward(e.id, 0.2)          # survived by pulling back
    elif e.action in ("flank", "shoot") and e.allies_near(enemies) > 2:
        kl.reward(e.id, 0.5)          # numbers pressed, damage dealt
    else:
        kl.reward(e.id, -0.1)         # died in a fair fight

kl.reward("enemy-0", 1.0, done=True)  # the fight is over for this unit: a win (-1 for a loss)

