from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game -------------------------------------------------
# Each player has a language; messages arrive as (sender, text).
players = {
    "ana": {"name": "Ana", "lang": "Spanish"},
    "ken": {"name": "Ken", "lang": "Japanese"},
}

incoming = [
    ("ana", "¿Vienes al pueblo? Hay una recompensa por el lobo."),
    ("ken", "ちょっと待って、装備を整える。"),
]

def show(sender_name, text):
    print(f"{sender_name}: {text}")

def deliver(recipient, sender_name, text):
    print(f"  -> {recipient} sees {sender_name}: {text}")

# --- translation -----------------------------------------------------------
# One translator per language pair, declared once and reused.
_translators = {}

def translator(source_lang, target_lang):
    key = (source_lang, target_lang)
    if key not in _translators:
        _translators[key] = kl.character(
            f"Translator {source_lang}->{target_lang}",
            soul=(
                f"You translate {source_lang} chat messages into {target_lang}. "
                f"Keep the tone, names, numbers and game terms exactly. "
                f"Reply with the translation only."
            ),
            offline=["[translation unavailable]"],
        )
    return _translators[key]

def translate(text, source_lang, target_lang):
    """Return the message in the reader's language. Instant, no streaming."""
    if source_lang == target_lang:
        return text
    return translator(source_lang, target_lang).say(text)

def relay(sender_id, text):
    """Send one message to every other player, each in their own language."""
    sender = players[sender_id]
    for pid, p in players.items():
        if pid == sender_id:
            continue
        shown = translate(text, sender["lang"], p["lang"])
        deliver(p["name"], sender["name"], shown)

# --- where the game would run it -------------------------------------------
for sender_id, text in incoming:
    show(players[sender_id]["name"], text)
    relay(sender_id, text)

