from kinloom import Kinloom

kl = Kinloom()

# --- Stand-in for the game -------------------------------------------------
PLAYER = "player-1"
GUARDS = ["Aldric", "Bryn", "Maud"]

# The guards exist in the world already (declared once, elsewhere).
# Here we only need their names and the fact they watch the streets.

def player_steals(item):
    """The game calls this when the player takes something they shouldn't."""
    return {"item": item, "place": "market"}

def guards_present():
    """Who is on duty right now, near the theft."""
    return ["Aldric", "Bryn"]  # Maud is off duty

def witnesses(guards):
    """Which guards actually saw it happen."""
    return [g for g in guards if g != "Bryn"]  # Bryn was looking away

# --- What the game does when the player steals ------------------------------

def on_theft(item):
    theft = player_steals(item)
    seen_by = witnesses(guards_present())

    # One event, tagged, with an impact: this is the "who saw what" record.
    kl.event(
        f"{PLAYER} stole the {theft['item']} in the {theft['place']}",
        by=PLAYER,
        seen_by=seen_by,
        tag="theft",
        impact=-0.5,
    )

    # Every guard who saw it tells the others, so the knowledge spreads.
    for guard in seen_by:
        for other in GUARDS:
            if other != guard:
                kl.meet(guard, other)

    return seen_by

# --- What a guard can ask the world -----------------------------------------

def guard_knows_about_theft(guard):
    return kl.knows(guard, PLAYER, "theft")

def guard_opinion_of_player(guard):
    return kl.opinion(guard, PLAYER)

def guard_reputation_among_guards():
    return kl.reputation(PLAYER, "guards")

# --- Where the game would call it -------------------------------------------

seen = on_theft("loaf of bread")
print("Saw the theft:", seen)

for guard in GUARDS:
    print(
        guard,
        "knows:", guard_knows_about_theft(guard),
        "opinion:", guard_opinion_of_player(guard),
    )

print("Reputation among guards:", guard_reputation_among_guards())

